// GET /api/ideas?q=search+term  -- q uses SQLite FTS5 when present
router.get('/', (req, res) => {
    const q = (req.query.q || '').trim();
    if (!q) {
        return res.json(db.prepare('SELECT * FROM ideas ORDER BY created_at DESC').all().map(serialize));
    }
    // Quote each token so FTS5 treats user input as a literal prefix match
    // instead of parsing it as query syntax (avoids 500s on '(', ':', '"', etc).
    const matchQuery = q.split(/\s+/).filter(Boolean)
        .map(t => `"${t.replace(/"/g, '""')}"*`)
        .join(' ');
    try {
        const rows = db.prepare(`
            SELECT ideas.* FROM ideas_fts
            JOIN ideas ON ideas.id = ideas_fts.id
            WHERE ideas_fts MATCH ?
            ORDER BY rank
        `).all(matchQuery);
        res.json(rows.map(serialize));
    } catch (e) {
        // Malformed FTS5 query (e.g. lone punctuation) - fall back to a plain substring scan.
        const like = `%${q}%`;
        const rows = db.prepare(
            'SELECT * FROM ideas WHERE title LIKE ? OR desc LIKE ? ORDER BY created_at DESC'
        ).all(like, like);
        res.json(rows.map(serialize));
    }
});

