import initSqlJs from 'sql.js';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const dataDir = path.join(__dirname, '..', 'data');
fs.mkdirSync(dataDir, { recursive: true });
const dbFile = path.join(dataDir, 'alba-content-hub.db');

// SQLite compiled to WASM (sql.js) instead of a native addon (better-sqlite3):
// this machine's Homebrew Node build segfaults inside napi_module_register_by_symbol
// when dlopen-ing any freshly node-gyp-compiled N-API addon (reproduced even after a
// clean from-source rebuild), so a native driver is a dead end here. sql.js runs the
// same SQLite (with FTS5) inside Node's WASM runtime - no native compile, no dlopen.
const SQL = await initSqlJs({
    locateFile: (file) => path.join(__dirname, '..', 'node_modules', 'sql.js', 'dist', file),
});

const existing = fs.existsSync(dbFile) ? fs.readFileSync(dbFile) : undefined;
const raw = new SQL.Database(existing);
raw.run('PRAGMA foreign_keys = ON;');

let inTransaction = false;

function persist() {
    if (inTransaction) return;
    fs.writeFileSync(dbFile, Buffer.from(raw.export()));
}

function toBindParams(args) {
    if (args.length === 1 && args[0] !== null && typeof args[0] === 'object' && !Array.isArray(args[0])) {
        const bound = {};
        for (const k of Object.keys(args[0])) bound['@' + k] = args[0][k];
        return bound;
    }
    return args;
}

function prepare(sql) {
    return {
        run(...args) {
            const stmt = raw.prepare(sql);
            try {
                stmt.bind(toBindParams(args));
                stmt.step();
            } finally {
                stmt.free();
            }
            const changes = raw.getRowsModified();
            persist();
            return { changes };
        },
        get(...args) {
            const stmt = raw.prepare(sql);
            try {
                stmt.bind(toBindParams(args));
                return stmt.step() ? stmt.getAsObject() : undefined;
            } finally {
                stmt.free();
            }
        },
        all(...args) {
            const stmt = raw.prepare(sql);
            const rows = [];
            try {
                stmt.bind(toBindParams(args));
                while (stmt.step()) rows.push(stmt.getAsObject());
            } finally {
                stmt.free();
            }
            return rows;
        },
    };
}

function exec(sql) {
    raw.run(sql);
    persist();
}

function transaction(fn) {
    return (...args) => {
        inTransaction = true;
        try {
            const result = fn(...args);
            inTransaction = false;
            persist();
            return result;
        } catch (e) {
            inTransaction = false;
            throw e;
        }
    };
}

export const db = { prepare, exec, transaction };

db.exec(`
CREATE TABLE IF NOT EXISTS ideas (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    desc TEXT DEFAULT '',
    format TEXT DEFAULT 'TG Пост',
    funnel TEXT DEFAULT 'TOFU',
    status TEXT DEFAULT 'idea',
    cta TEXT DEFAULT '',
    target_groups TEXT DEFAULT '[]',
    metrics_views INTEGER DEFAULT 0,
    metrics_saves INTEGER DEFAULT 0,
    metrics_clicks INTEGER DEFAULT 0,
    metrics_leads INTEGER DEFAULT 0,
    created_at INTEGER DEFAULT (unixepoch())
);

CREATE VIRTUAL TABLE IF NOT EXISTS ideas_fts USING fts5(
    id UNINDEXED,
    title,
    desc,
    format,
    funnel,
    content=''
);

CREATE TABLE IF NOT EXISTS scheduled_events (
    id INTEGER PRIMARY KEY,
    idea_id TEXT REFERENCES ideas(id) ON DELETE SET NULL,
    title TEXT NOT NULL,
    date_str TEXT,
    raw_date TEXT NOT NULL,
    color TEXT,
    format TEXT,
    cta TEXT,
    desc TEXT
);

CREATE TABLE IF NOT EXISTS plan_settings (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    daily INTEGER NOT NULL DEFAULT 1,
    weekly INTEGER NOT NULL DEFAULT 7
);
INSERT OR IGNORE INTO plan_settings (id, daily, weekly) VALUES (1, 1, 7);

CREATE TABLE IF NOT EXISTS telegram_settings (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    token TEXT DEFAULT '',
    chat_id TEXT DEFAULT ''
);
INSERT OR IGNORE INTO telegram_settings (id, token, chat_id) VALUES (1, '', '');
`);

function reindexIdeaFts(idea) {
    db.prepare('DELETE FROM ideas_fts WHERE id = ?').run(idea.id);
    db.prepare(
        'INSERT INTO ideas_fts (id, title, desc, format, funnel) VALUES (?, ?, ?, ?, ?)'
    ).run(idea.id, idea.title, idea.desc || '', idea.format || '', idea.funnel || '');
}

export function reindexAllIdeas() {
    db.exec('DELETE FROM ideas_fts');
    for (const idea of db.prepare('SELECT * FROM ideas').all()) {
        reindexIdeaFts(idea);
    }
}

export { reindexIdeaFts };

