import { createClient } from '@libsql/client';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

function makeClient() {
    const url = process.env.TURSO_DATABASE_URL;
    if (url) {
        // Production (Vercel) and any dev session pointed at a real Turso db.
        return createClient({ url, authToken: process.env.TURSO_AUTH_TOKEN });
    }
    // Local dev fallback: a file-based libSQL db, no Turso account needed.
    // Vercel's filesystem is read-only/ephemeral per invocation, so this branch
    // must never be reached in production - set TURSO_DATABASE_URL there.
    const dataDir = path.join(__dirname, '..', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    return createClient({ url: `file:${path.join(dataDir, 'alba-content-hub.db')}` });
}

export const db = makeClient();

await db.executeMultiple(`
CREATE TABLE IF NOT EXISTS ideas (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    desc TEXT DEFAULT '',
    format TEXT DEFAULT 'TG Пост',
    funnel TEXT DEFAULT 'TOFU',
    status TEXT DEFAULT 'idea',
    cta TEXT DEFAULT '',
    target_groups TEXT DEFAULT '[]',
    metrics_views INTEGER DEFAULT 0,
    metrics_saves INTEGER DEFAULT 0,
    metrics_clicks INTEGER DEFAULT 0,
    metrics_leads INTEGER DEFAULT 0,
    created_at INTEGER DEFAULT (strftime('%s','now'))
);
CREATE INDEX IF NOT EXISTS idx_ideas_title ON ideas(title);
CREATE INDEX IF NOT EXISTS idx_ideas_status ON ideas(status);

CREATE TABLE IF NOT EXISTS scheduled_events (
    id INTEGER PRIMARY KEY,
    idea_id TEXT REFERENCES ideas(id) ON DELETE SET NULL,
    title TEXT NOT NULL,
    date_str TEXT,
    raw_date TEXT NOT NULL,
    color TEXT,
    format TEXT,
    cta TEXT,
    desc TEXT
);
CREATE INDEX IF NOT EXISTS idx_events_raw_date ON scheduled_events(raw_date);

CREATE TABLE IF NOT EXISTS plan_settings (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    daily INTEGER NOT NULL DEFAULT 1,
    weekly INTEGER NOT NULL DEFAULT 7
);
INSERT OR IGNORE INTO plan_settings (id, daily, weekly) VALUES (1, 1, 7);

CREATE TABLE IF NOT EXISTS telegram_settings (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    token TEXT DEFAULT '',
    chat_id TEXT DEFAULT ''
);
INSERT OR IGNORE INTO telegram_settings (id, token, chat_id) VALUES (1, '', '');
`);

import { Router } from 'express';
import { db } from '../db.js';

const router = Router();

function serialize(row) {
    return {
        id: row.id,
        title: row.title,
        desc: row.desc,
        format: row.format,
        funnel: row.funnel,
        status: row.status,
        cta: row.cta,
        targetGroups: JSON.parse(row.target_groups || '[]'),
        metrics: {
            views: row.metrics_views,
            saves: row.metrics_saves,
            clicks: row.metrics_clicks,
            leads: row.metrics_leads,
        },
    };
}

const upsertSql = `
    INSERT INTO ideas (id, title, desc, format, funnel, status, cta, target_groups, metrics_views, metrics_saves, metrics_clicks, metrics_leads)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
        title = excluded.title, desc = excluded.desc, format = excluded.format,
        funnel = excluded.funnel, status = excluded.status, cta = excluded.cta,
        target_groups = excluded.target_groups,
        metrics_views = excluded.metrics_views, metrics_saves = excluded.metrics_saves,
        metrics_clicks = excluded.metrics_clicks, metrics_leads = excluded.metrics_leads
`;

function upsertArgs(row) {
    return [row.id, row.title, row.desc, row.format, row.funnel, row.status, row.cta,
        row.target_groups, row.metrics_views, row.metrics_saves, row.metrics_clicks, row.metrics_leads];
}

// GET /api/ideas?q=search+term  -- indexed LIKE scan over title/desc
router.get('/', async (req, res) => {
    const q = (req.query.q || '').trim();
    if (!q) {
        const result = await db.execute('SELECT * FROM ideas ORDER BY created_at DESC');
        return res.json(result.rows.map(serialize));
    }
    const like = `%${q}%`;
    const result = await db.execute({
        sql: 'SELECT * FROM ideas WHERE title LIKE ? OR desc LIKE ? OR format LIKE ? OR funnel LIKE ? ORDER BY created_at DESC',
        args: [like, like, like, like],
    });
    res.json(result.rows.map(serialize));
});

router.post('/', async (req, res) => {
    const b = req.body || {};
    if (!b.title || !String(b.title).trim()) {
        return res.status(400).json({ error: 'title is required' });
    }
    const id = String(Date.now());
    await db.execute({
        sql: upsertSql,
        args: upsertArgs({
            id,
            title: b.title.trim(),
            desc: b.desc || '',
            format: b.format || 'TG Пост',
            funnel: b.funnel || 'TOFU',
            status: b.status || 'idea',
            cta: b.cta || '',
            target_groups: JSON.stringify(b.targetGroups || []),
            metrics_views: 0, metrics_saves: 0, metrics_clicks: 0, metrics_leads: 0,
        }),
    });
    const result = await db.execute({ sql: 'SELECT * FROM ideas WHERE id = ?', args: [id] });
    res.status(201).json(serialize(result.rows[0]));
});

router.put('/:id', async (req, res) => {
    const existingRes = await db.execute({ sql: 'SELECT * FROM ideas WHERE id = ?', args: [req.params.id] });
    const existing = existingRes.rows[0];
    if (!existing) return res.status(404).json({ error: 'idea not found' });

    const b = req.body || {};
    const merged = {
        id: existing.id,
        title: b.title !== undefined ? String(b.title).trim() : existing.title,
        desc: b.desc !== undefined ? b.desc : existing.desc,
        format: b.format !== undefined ? b.format : existing.format,
        funnel: b.funnel !== undefined ? b.funnel : existing.funnel,
        status: b.status !== undefined ? b.status : existing.status,
        cta: b.cta !== undefined ? b.cta : existing.cta,
        target_groups: b.targetGroups !== undefined ? JSON.stringify(b.targetGroups) : existing.target_groups,
        metrics_views: b.metrics?.views !== undefined ? b.metrics.views : existing.metrics_views,
        metrics_saves: b.metrics?.saves !== undefined ? b.metrics.saves : existing.metrics_saves,
        metrics_clicks: b.metrics?.clicks !== undefined ? b.metrics.clicks : existing.metrics_clicks,
        metrics_leads: b.metrics?.leads !== undefined ? b.metrics.leads : existing.metrics_leads,
    };
    await db.execute({ sql: upsertSql, args: upsertArgs(merged) });
    const result = await db.execute({ sql: 'SELECT * FROM ideas WHERE id = ?', args: [existing.id] });
    res.json(serialize(result.rows[0]));
});

router.delete('/:id', async (req, res) => {
    const del = await db.execute({ sql: 'DELETE FROM ideas WHERE id = ?', args: [req.params.id] });
    await db.execute({ sql: 'DELETE FROM scheduled_events WHERE idea_id = ?', args: [req.params.id] });
    if (Number(del.rowsAffected) === 0) return res.status(404).json({ error: 'idea not found' });
    res.status(204).end();
});

// Bulk replace, used by JSON import
router.post('/import', async (req, res) => {
    const items = req.body;
    if (!Array.isArray(items)) return res.status(400).json({ error: 'expected an array of ideas' });

    const tx = await db.transaction('write');
    try {
        // Only ideas are replaced - scheduled_events survive with idea_id set to
        // NULL via the FK's ON DELETE SET NULL, same as the old localStorage
        // import which never touched the calendar.
        await tx.execute('DELETE FROM ideas');
        for (const item of items) {
            if (!item.title) continue;
            await tx.execute({
                sql: upsertSql,
                args: upsertArgs({
                    id: item.id != null ? String(item.id) : String(Date.now() + Math.random()),
                    title: item.title,
                    desc: item.desc || '',
                    format: item.format || 'TG Пост',
                    funnel: item.funnel || 'TOFU',
                    status: item.status || 'idea',
                    cta: item.cta || '',
                    target_groups: JSON.stringify(item.targetGroups || []),
                    metrics_views: item.metrics?.views || 0,
                    metrics_saves: item.metrics?.saves || 0,
                    metrics_clicks: item.metrics?.clicks || 0,
                    metrics_leads: item.metrics?.leads || 0,
                }),
            });
        }
        await tx.commit();
    } catch (e) {
        await tx.rollback();
        throw e;
    }
    const result = await db.execute('SELECT * FROM ideas ORDER BY created_at DESC');
    res.json(result.rows.map(serialize));
});

export default router;

import { Router } from 'express';
import { db } from '../db.js';

const router = Router();

function serialize(row) {
    return {
        id: row.id,
        ideaId: row.idea_id,
        title: row.title,
        dateStr: row.date_str,
        rawDate: row.raw_date,
        color: row.color,
        format: row.format,
        cta: row.cta,
        desc: row.desc,
    };
}

router.get('/', async (req, res) => {
    const result = await db.execute('SELECT * FROM scheduled_events ORDER BY raw_date ASC');
    res.json(result.rows.map(serialize));
});

router.post('/', async (req, res) => {
    const b = req.body || {};
    if (!b.rawDate || !b.title) return res.status(400).json({ error: 'rawDate and title are required' });

    const id = Date.now();
    await db.execute({
        sql: `
            INSERT INTO scheduled_events (id, idea_id, title, date_str, raw_date, color, format, cta, desc)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `,
        args: [id, b.ideaId ?? null, b.title, b.dateStr || '', b.rawDate,
            b.color || '#0a84ff', b.format || 'TG Пост', b.cta || '', b.desc || ''],
    });
    const result = await db.execute({ sql: 'SELECT * FROM scheduled_events WHERE id = ?', args: [id] });
    res.status(201).json(serialize(result.rows[0]));
});

router.delete('/:id', async (req, res) => {
    const del = await db.execute({ sql: 'DELETE FROM scheduled_events WHERE id = ?', args: [req.params.id] });
    if (Number(del.rowsAffected) === 0) return res.status(404).json({ error: 'event not found' });
    res.status(204).end();
});

export default router;

import { Router } from 'express';
import { db } from '../db.js';

const router = Router();

router.get('/plan', async (req, res) => {
    const result = await db.execute('SELECT daily, weekly FROM plan_settings WHERE id = 1');
    res.json(result.rows[0]);
});

router.put('/plan', async (req, res) => {
    const daily = Math.max(1, parseInt(req.body?.daily, 10) || 1);
    const weekly = Math.max(1, parseInt(req.body?.weekly, 10) || 7);
    await db.execute({ sql: 'UPDATE plan_settings SET daily = ?, weekly = ? WHERE id = 1', args: [daily, weekly] });
    res.json({ daily, weekly });
});

// Telegram settings are write-mostly: the bot token never round-trips back to the
// browser in full, only a masked preview + whether one is configured.
router.get('/telegram', async (req, res) => {
    const result = await db.execute('SELECT token, chat_id FROM telegram_settings WHERE id = 1');
    const row = result.rows[0];
    const hasToken = Boolean(row.token);
    res.json({
        chatId: row.chat_id || '',
        hasToken,
        tokenPreview: hasToken ? `••••${row.token.slice(-4)}` : '',
    });
});

router.put('/telegram', async (req, res) => {
    const { token, chatId } = req.body || {};
    const currentRes = await db.execute('SELECT token, chat_id FROM telegram_settings WHERE id = 1');
    const current = currentRes.rows[0];
    const nextToken = token !== undefined && token !== '' ? token.trim() : current.token;
    const nextChatId = chatId !== undefined ? chatId.trim() : current.chat_id;
    await db.execute({ sql: 'UPDATE telegram_settings SET token = ?, chat_id = ? WHERE id = 1', args: [nextToken, nextChatId] });
    res.json({
        chatId: nextChatId,
        hasToken: Boolean(nextToken),
        tokenPreview: nextToken ? `••••${nextToken.slice(-4)}` : '',
    });
});

export default router;

import { Router } from 'express';
import { db } from '../db.js';

const router = Router();

// The bot token lives only in the database; it is read here and used in a
// server-to-server fetch, so it never reaches the browser.
router.post('/post', async (req, res) => {
    const { ideaId } = req.body || {};
    const ideaRes = await db.execute({ sql: 'SELECT * FROM ideas WHERE id = ?', args: [ideaId] });
    const idea = ideaRes.rows[0];
    if (!idea) return res.status(404).json({ error: 'idea not found' });

    const settingsRes = await db.execute('SELECT token, chat_id FROM telegram_settings WHERE id = 1');
    const settings = settingsRes.rows[0];
    if (!settings.token || !settings.chat_id) {
        return res.status(400).json({ error: 'Telegram bot is not configured' });
    }

    const messageText = `*${idea.title}*\n\n${idea.desc || ''}\n\n👉 _${idea.cta || ''}_\n\n#${idea.funnel || 'TOFU'} #AlbaCreation`;

    try {
        const tgRes = await fetch(`https://api.telegram.org/bot${settings.token}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: settings.chat_id, text: messageText, parse_mode: 'Markdown' }),
        });
        const data = await tgRes.json();
        if (!data.ok) return res.status(502).json({ error: data.description || 'Telegram API error' });
        res.json({ ok: true });
    } catch (e) {
        res.status(502).json({ error: 'Failed to reach Telegram API' });
    }
});

export default router;

import express from 'express';
import cors from 'cors';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

import ideasRouter from './routes/ideas.js';
import eventsRouter from './routes/events.js';
import settingsRouter from './routes/settings.js';
import telegramRouter from './routes/telegram.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();

app.use(cors());
app.use(express.json());

app.use('/api/ideas', ideasRouter);
app.use('/api/events', eventsRouter);
app.use('/api/settings', settingsRouter);
app.use('/api/telegram', telegramRouter);

// Traditional Node hosting (pnpm start): serve the Vite-built frontend from the
// same process. On Vercel this branch is never hit - static files are served
// straight from the "dist" output directory, and only /api/* is rewritten here.
const distDir = path.join(__dirname, '..', 'dist');
if (fs.existsSync(distDir)) {
    app.use(express.static(distDir));
    app.get(/.*/, (req, res, next) => {
        if (req.path.startsWith('/api/')) return next();
        res.sendFile(path.join(distDir, 'index.html'));
    });
}

// Route handlers are async; this turns a rejected promise into a JSON error
// response instead of Express's default HTML error page.
app.use((err, req, res, next) => {
    console.error(err);
    if (res.headersSent) return next(err);
    res.status(500).json({ error: err.message || 'Internal server error' });
});

export default app;

import app from './app.js';

const PORT = process.env.API_PORT || 4000;
app.listen(PORT, () => {
    console.log(`Alba Content Hub API listening on http://localhost:${PORT}`);
});

// Vercel serverless entry point. Every request to /api/* is rewritten here
// (see vercel.json) and handled by the same Express app used for local dev.
import app from '../server/app.js';

export default app;

{
  "buildCommand": "vite build",
  "outputDirectory": "dist",
  "rewrites": [
    { "source": "/api/:path*", "destination": "/api" }
  ]
}

content.text:
Запушено в `main` → это автоматически запустит новый деплой на Vercel (если у тебя подключён GitHub-интеграция), либо нужно будет нажать Redeploy вручную — там же добавь переменные окружения из прошлого сообщения.

---

## Что такое Turso

Это облачный сервис для SQLite — по сути та же самая база данных SQLite, которую ты знаешь (тот же SQL, те же файлы), только:

- **живёт не на диске твоего компьютера, а в облаке** — доступна по сети из любого места (включая serverless-функции Vercel, у которых своей постоянной файловой системы нет);
- под капотом — **libSQL**, форк SQLite с добавленной сетевой репликацией;
- к ней обращаются через HTTP/WebSocket-клиент (`@libsql/client`, который я подключил в проект), а не через файл на диске;
- **бесплатный тариф** щедрый: 500 баз, 9 ГБ хранилища, ~1 млрд чтений в месяц — для внутреннего инструмента вроде твоего хаба с огромным запасом;
- ты уже создал свою базу командой `turso db create alba-content-hub`, и я проверил напрямую через `turso db shell`, что данные туда реально пишутся.

