/* CONTENT PLAN - QUARTERLY TIMELINE */
.plan-timeline-wrap { overflow-x: auto; margin-top: 14px; padding: 4px 4px 18px; }
.plan-timeline-wrap::-webkit-scrollbar { height: 8px; }
.plan-timeline-wrap::-webkit-scrollbar-track { background: rgba(255,255,255,0.04); border-radius: 8px; }
.plan-timeline-wrap::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.16); border-radius: 8px; }
.plan-timeline-wrap::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.28); }

.plan-timeline { display: flex; align-items: stretch; min-width: max-content; }
.timeline-card {
    position: relative; width: 320px; flex-shrink: 0;
    background: linear-gradient(165deg, rgba(255,255,255,0.06), rgba(255,255,255,0.015) 65%);
    border-radius: 20px; padding: 22px 20px 20px; border: 1px solid rgba(255,255,255,0.09);
    display: flex; flex-direction: column; gap: 12px; overflow: hidden;
    transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}
.timeline-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px;
    background: var(--card-accent, var(--accent-blue));
    box-shadow: 0 0 18px 0 var(--card-accent, var(--accent-blue));
}
.timeline-card:hover {
    transform: translateY(-3px);
    border-color: color-mix(in srgb, var(--card-accent, var(--accent-blue)) 45%, rgba(255,255,255,0.09));
    box-shadow: 0 16px 36px -14px rgba(0,0,0,0.6);
}
.timeline-quarter-badge {
    position: absolute; top: -8px; right: -6px; font-size: 76px; font-weight: 800;
    color: var(--card-accent, var(--accent-blue)); opacity: 0.08; line-height: 1;
    pointer-events: none; user-select: none; letter-spacing: -4px;
}
.timeline-card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.timeline-index-pill {
    display: inline-flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: 800; letter-spacing: 0.5px;
    color: var(--card-accent, var(--accent-blue));
    background: color-mix(in srgb, var(--card-accent, var(--accent-blue)) 18%, transparent);
    border-radius: 6px; padding: 3px 7px; flex-shrink: 0; margin-top: 4px;
}
.timeline-card-title {
    flex: 1; min-width: 0; background: none; border: none; color: var(--text-primary);
    font-size: 18px; font-weight: 700; padding: 4px 0; border-bottom: 1px solid transparent;
    text-overflow: ellipsis; overflow: hidden; white-space: nowrap;
}
.timeline-card-title:focus { outline: none; border-bottom-color: var(--card-accent, var(--accent-blue)); text-overflow: clip; }
.timeline-card-period {
    background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.09);
    border-radius: 8px; padding: 7px 11px; font-size: 12px; font-weight: 600; color: var(--text-secondary);
    transition: border-color 0.15s ease;
}
.timeline-card-period:focus { outline: none; border-color: var(--card-accent, var(--accent-blue)); }
.timeline-card-text {
    width: 100%; background: rgba(0,0,0,0.3);
    border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; color: var(--text-primary);
    font-size: 13px; line-height: 1.6; padding: 12px; resize: none; overflow: hidden;
    font-family: inherit; transition: border-color 0.15s ease, background 0.15s ease;
}
.timeline-card-text:focus { outline: none; border-color: var(--card-accent, var(--accent-blue)); background: rgba(0,0,0,0.42); }

.timeline-arrow {
    position: relative; display: flex; align-items: center; justify-content: center;
    width: 52px; flex-shrink: 0;
}
.timeline-arrow::before {
    content: ''; position: absolute; left: 0; right: 0; top: 50%; height: 2px; transform: translateY(-50%);
    background: linear-gradient(90deg, rgba(255,255,255,0.04), rgba(255,255,255,0.22), rgba(255,255,255,0.04));
}
.timeline-arrow-icon {
    position: relative; z-index: 1; width: 30px; height: 30px; border-radius: 50%;
    background: var(--bg-base); border: 1px solid rgba(255,255,255,0.16);
    display: flex; align-items: center; justify-content: center;
    color: var(--text-secondary); font-size: 13px; font-weight: 700;
}

